//! SPAN interface actions preserve actual native paint and editor/link state.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn span_interface_actual_app_pointer_attribute_paint_editor_and_links(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-span-interface-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}#data{margin:0;font-size:12px;font-weight:normal;line-height:16px;display:block;position:absolute;left:20px;top:20px;width:120px;height:32px;background:#114455}#data[data-state="ready"]{background:#cc2244}#data[data-state="done"]{background:#2244cc}#data:not([data-state]){background:#228844}#go{position:absolute;left:220px;top:20px;width:160px;height:32px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}</style><body><span id=data data-state=initial>Fallback span</span><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><button id=go type=button>Change metadata</button><div id=destination></div><script>var x=document.getElementById('data'),attr=x.getAttributeNode('data-state'),first=x.firstChild,round=0,watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'native pointer';var focus=document.activeElement;if(!(x instanceof HTMLSpanElement)||Object.getPrototypeOf(x)!==HTMLSpanElement.prototype)throw 'actual canonical span';if(round===0){x.setAttribute('data-state','ready');}else if(round===1){attr.nodeValue='done';}else{x.removeAttribute('data-state');}var records=watch.takeRecords();if(x.getAttribute('data-state')!==['ready','done',null][round]||x.firstChild!==first||x.textContent!=='Fallback span'||records.length!==1||records[0].attributeName!=='data-state'||records[0].oldValue!==['initial','ready','done'][round]||document.activeElement!==focus||document.getElementById('neighbor').value!=='edited neighbor')throw 'actual value state';if(round<2){if(attr.ownerElement!==x||x.getAttributeNode('data-state')!==attr)throw 'same actual Attr';}else{if(attr.ownerElement!==null||attr.value!=='done')throw 'removed Attr';}document.title='SPAN interface '+round;round++;};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);let initial=app.draw();assert_eq!(initial.pixels[(app.content_top()+40)as usize*initial.width+110],0x114455);
 let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let scroll=app.scroll;
 for round in 0..3{let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert!(!app.failed,"{}",app.status);assert_eq!(app.document.title,format!("SPAN interface {round}"));let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+40)as usize*painted.width+110],[0xcc2244,0x2244cc,0x228844][round]);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);assert_eq!(app.scroll,scroll);}
}
